-- ============================================================
-- VOLLSTAENDIGES Postgres-Schema: ALLE 179 Tabellen aus dem
-- MySQL-Produktions-Dump vom 26.02.2026, konvertiert + verifiziert.
-- Zweck: kompletter Neon-Branch als ERSATZ fuer den alten MySQL-Server.
-- Foreign Keys bewusst weggelassen (Import-Reihenfolge egal).
-- ============================================================

CREATE TABLE IF NOT EXISTS "idk_agenti_activity" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "employee_id" int NOT NULL,
  "activity_status" int DEFAULT '0',
  "activity_pocetak" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "activity_kraj" timestamp DEFAULT NULL,
  "activity_ukupno" time DEFAULT '00:00:00',
  "activity_aktivan" int NOT NULL DEFAULT '1',
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS "idk_analitika" (
  "analizika_id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "analitika_rating" int DEFAULT NULL,
  "analitika_datum" timestamp DEFAULT NULL,
  PRIMARY KEY (analizika_id)
);

CREATE TABLE IF NOT EXISTS "idk_api_clients" (
  "client_id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "client_name" varchar(525) NOT NULL,
  "client_token" varchar(525) NOT NULL,
  PRIMARY KEY (client_id)
);

CREATE TABLE IF NOT EXISTS "idk_appointment_invite_links" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "candidate_id" int NOT NULL,
  "interview_id" int NOT NULL,
  "link_status" int NOT NULL,
  "date_sent" timestamp DEFAULT NULL,
  "date_open" timestamp DEFAULT NULL,
  "date_confirmed" timestamp DEFAULT NULL,
  "date_archived" timestamp DEFAULT NULL,
  "send_key" varchar(50) NOT NULL,
  "sent_days_before" int DEFAULT NULL,
  "counter_sent" int NOT NULL,
  PRIMARY KEY (id)
);
CREATE INDEX IF NOT EXISTS "interview_id" ON "idk_appointment_invite_links" (interview_id);

CREATE TABLE IF NOT EXISTS "idk_bot_obavijesti" (
  "bo_id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "bo_kandidat_id" int NOT NULL,
  "bo_nalog_id" int NOT NULL,
  "bo_poslana" int NOT NULL,
  "bo_odgovor" int DEFAULT '0',
  PRIMARY KEY (bo_id)
);

CREATE TABLE IF NOT EXISTS "idk_candidate_language_logs" (
  "cll_id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "cll_candidate_id" int NOT NULL,
  "cll_cvl_id" int NOT NULL,
  "cll_status" int NOT NULL,
  "cll_date" timestamp NOT NULL,
  "cll_employee_id" int NOT NULL,
  "cll_days_count" int DEFAULT NULL,
  PRIMARY KEY (cll_id)
);

CREATE TABLE IF NOT EXISTS "idk_candidate_verified_languages" (
  "cvl_id" int NOT NULL,
  "cvl_status" int NOT NULL,
  "cvl_active" int NOT NULL DEFAULT '0',
  "cvl_course1_started" date DEFAULT NULL,
  "cvl_course1_ended" date DEFAULT NULL,
  "cvl_course2_started" date DEFAULT NULL,
  "cvl_course2_ended" date DEFAULT NULL,
  "cvl_motive_start" date DEFAULT NULL,
  "cvl_motive_end" date DEFAULT NULL,
  "cvl_exam_date" date DEFAULT NULL,
