);
CREATE INDEX IF NOT EXISTS "cvl_active" ON "idk_candidate_verified_languages" (cvl_active);

CREATE TABLE IF NOT EXISTS "idk_chat_question" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "type" text NOT NULL,
  "question_order" int DEFAULT NULL,
  "question" text NOT NULL,
  "answer" text,
  "parentQuestion" int DEFAULT NULL,
  "deletedAt" timestamp DEFAULT NULL,
