);

CREATE TABLE IF NOT EXISTS "idk_chat_type" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "name" varchar(150) NOT NULL,
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS "idk_clients" (
  "client_id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "client_name" varchar(250) DEFAULT NULL,
  "client_country" varchar(255) DEFAULT NULL,
  "client_region" varchar(100) DEFAULT NULL,
  "client_city" varchar(250) DEFAULT NULL,
  "client_address" varchar(250) DEFAULT NULL,
  "client_pp" int DEFAULT NULL,
  "client_telephone" varchar(250) DEFAULT NULL,
  "client_email" varchar(250) DEFAULT NULL,
  "client_origin" int NOT NULL,
  "client_recommendation" int DEFAULT NULL,
  "client_recommendation_company" int DEFAULT NULL,
  "client_fc_or_sales" int NOT NULL,
  "client_fc_status" int NOT NULL,
  "client_sales_status" int NOT NULL,
  "client_manager" int DEFAULT NULL,
  "client_sales_manager" int DEFAULT NULL,
  "client_datum_zvanja" date DEFAULT NULL,
  "client_contract" int NOT NULL DEFAULT '0',
  "client_description" text,
