  "company_zipcode" varchar(50) DEFAULT NULL,
  "company_city" varchar(150) DEFAULT NULL,
  "company_state" varchar(150) DEFAULT NULL,
  "company_country" varchar(150) DEFAULT NULL,
  "company_info" text,
  "company_inote" text,
  "company_logo" varchar(50) DEFAULT NULL,
  "company_contact_type" varchar(150) DEFAULT NULL,
